/* M48: exact memory arithmetic across 24 unprefixed real32/64 and FI16/32
 * forms, in x86/x64 interpreter and JIT. All golden values are integer literals
 * generated with independent Fraction arithmetic, never from a component run.
 * Exact completion checks full raw80 ST0/C1 with no pop. M50 promotes the
 * PM1 inexact controls; other compatibility behavior is retained. FIP and C0/C2/C3 are
 * excluded. Original real64-denormal controls preseed FPSR.IDC, so they do not
 * establish fresh IDC behavior. No NaN, masked-empty or zero-divisor parity. */
#pragma STDC FENV_ACCESS ON
#include "hb_decoder.h"
#include "hb_env.h"
#include "hb_lifter.h"
#include "hb_memory.h"
#include "hb_runtime.h"
