#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
enum { PAGE_BYTES=16384 };
enum { ADD,MUL,SUB,SUBR,DIV,DIVR };
enum { REAL32,REAL64,INT16,INT32 };
enum { KEEP,CANCEL,XOR };
enum { NORMAL,PENDING,RESERVED,INEXACT,EMPTY,SOURCE_DENORMAL,SOURCE_INFINITY };
enum { INTERIOR,EDGE,NO_READ,TRUNCATED,UNMAPPED };
enum { COMMON,CROSS,ZERO,PRECISION,TYPED,UNCACHED,PENDING_GROUP,RESERVED_GROUP,
       INEXACT_GROUP,EMPTY_GROUP,SPANS,EMPTY_FAULT,SOURCE_DENORMAL_GROUP,SOURCE_INFINITY_GROUP,GROUPS };
enum { RAW,STATE,DECODE,EXECUTION,HOST,MEMORY,CATEGORIES };
static const uint64_t CODE=UINT64_C(0x7200000),DATA=UINT64_C(0x7210000),DENIED=UINT64_C(0x7218000);
static unsigned checks,failures,executions,exact_cases,legacy_cases,empty_cases,memory_fault_cases;
static unsigned category_failures[CATEGORIES],group_cases[GROUPS];
static char phase[220]="setup";
static int check_kind(int ok,const char *what,unsigned category)
{++checks;if(!ok){++failures;++category_failures[category];if(failures<=80)fprintf(stderr,"FAIL %s: %s\n",phase,what);}return ok;}
static int check(int ok,const char *what){return check_kind(ok,what,STATE);}
static void put16(uint8_t *p,uint16_t n){p[0]=(uint8_t)n;p[1]=(uint8_t)(n>>8);}
static void put64(uint8_t *p,uint64_t n){for(unsigned i=0;i<8;++i)p[i]=(uint8_t)(n>>(8*i));}
typedef struct {uint16_t se;uint64_t sig,preview;unsigned tag;} raw_t;
typedef struct {const char *name;raw_t st0;uint64_t memory[4];raw_t result;unsigned zero_rule;} sample_t;
