static unsigned preview_tag(uint64_t bits)
{uint64_t mag=bits&UINT64_C(0x7fffffffffffffff);unsigned exp=(unsigned)(mag>>52);return !mag?1u:(exp==0||exp==0x7ff)?2u:0u;}
static raw_t answer(const fixture_t *f,const sample_t *s,unsigned rc)
{
    raw_t r=s->result;
    if(s->zero_rule!=KEEP){
        unsigned negative;
        if(s->zero_rule==CANCEL)negative=rc==1;
        else{
            uint64_t m=s->memory[f->form->format];unsigned shift=f->form->format==REAL64?63:f->form->format==INT16?15:31;
            negative=(unsigned)(s->st0.se>>15)^((unsigned)(m>>shift)&1u);
        }
        r.se=(uint16_t)(negative<<15);r.sig=0;r.preview=(uint64_t)negative<<63;r.tag=1;
    }
    return r;
}
